class Solution:
    def findSubstring(self, s: str, words: List[str]) -> List[int]:
        L, k = len(words[0]), len(words)
        need = Counter(words)
        res = []
        for off in range(L):
            l, cnt, used = off, defaultdict(int), 0
            for r in range(off, len(s) - L + 1, L):
                w = s[r:r + L]
                if w not in need:
                    l, cnt, used = r + L, defaultdict(int), 0
                    continue
                cnt[w] += 1
                used += 1
                while cnt[w] > need[w]:
                    cnt[s[l:l + L]] -= 1
                    used -= 1
                    l += L
                if used == k:
                    res.append(l)
        return sorted(res)

